Alter Procedure [dbo].[HRS_Task_ADD]
(
	@EmployeeID bigint = null,
	@TaskFrom date,
	@TaskTo date = null,
	@RequestUser bigint = null,
	@OtherDepartmentID int = 0,
	@OtherPositionID nvarchar(20) = 0,
	@PositionID nvarchar(20) = 0,
	@Work nvarchar(200) = null,
	@DecidedNo nvarchar(20) = null,
	@DecidedDate date = null,
	@DecidedUser bigint = 0,
	@IsSigned bit = 0,
	@Description nvarchar(200) = null,
	@CreatedUser nvarchar(20),
	@FromDepartmentID int = 0,
	@ToDepartmentID int = 0,
	@DecidedDepartmentName nvarchar(50) = null,
	@DecidedFullName nvarchar(50) = null,
	@ToOfficeName nvarchar(50) = null,
	@ToDepartmentName nvarchar(50) = null,
	@CurrentPositionID nvarchar(20) = 0,
	@EndTask_DecidedNo nvarchar(20) = null,
	@EndTask_DecidedDate date = null,
	@EndTask_DecidedUser bigint = 0,
	@EndTask_IsSigned bit = 0,
	@EndTask_Description nvarchar(200) = null,
	@EndTask_DecidedDepartmentName nvarchar(50) = null,
	@EndTask_DecidedFullName nvarchar(50) = null,
	@TaskTypeID int = 0,
	@Link nvarchar(500) = null
)
As
Begin

	Set Nocount Off

	Insert Into [HRS_Task]
	(
		[EmployeeID],
		[TaskFrom],
		[TaskTo],
		[RequestUser],
		[OtherDepartmentID],
		[OtherPositionID],
		[PositionID],
		[Work],
		[DecidedNo],
		[DecidedDate],
		[DecidedUser],
		[IsSigned],
		[Description],
		[CreatedUser],
		[FromDepartmentID],
		[ToDepartmentID],
		[DecidedDepartmentName],
		[DecidedFullName],
		[ToOfficeName],
		[ToDepartmentName],
		[CurrentPositionID],
		[EndTask_DecidedNo],
		[EndTask_DecidedDate],
		[EndTask_DecidedUser],
		[EndTask_IsSigned],
		[EndTask_Description],
		[EndTask_DecidedDepartmentName],
		[EndTask_DecidedFullName],
		[TaskTypeID],
		[Link]
	)
	Values
	(
		@EmployeeID,
		@TaskFrom,
		@TaskTo,
		@RequestUser,
		@OtherDepartmentID,
		@OtherPositionID,
		@PositionID,
		@Work,
		@DecidedNo,
		@DecidedDate,
		@DecidedUser,
		@IsSigned,
		@Description,
		@CreatedUser,
		@FromDepartmentID,
		@ToDepartmentID,
		@DecidedDepartmentName,
		@DecidedFullName,
		@ToOfficeName,
		@ToDepartmentName,
		@CurrentPositionID,
		@EndTask_DecidedNo,
		@EndTask_DecidedDate,
		@EndTask_DecidedUser,
		@EndTask_IsSigned,
		@EndTask_Description,
		@EndTask_DecidedDepartmentName,
		@EndTask_DecidedFullName,
		@TaskTypeID,
		@Link
	)

	Select Cast(SCOPE_IDENTITY() As bigint)

End
