        public static string GetDisplayFileName(string relativePath)
        {
            if (string.IsNullOrWhiteSpace(relativePath))
                return string.Empty;
            return Path.GetFileName(relativePath.Replace('/', Path.DirectorySeparatorChar));
        }

        public static bool HasAttachment(string relativePath)
        {
            return !string.IsNullOrWhiteSpace(relativePath);
        }

        /// <summary>
        /// Tạo URL xem/tải tập tin (viewer hoặc DownloadFile.ashx).
        /// </summary>
        public static bool TryBuildViewUrl(string relativePath, string userName, out string url, out string errorMessage)
        {
            url = string.Empty;
            errorMessage = string.Empty;

            if (string.IsNullOrWhiteSpace(relativePath))
            {
                errorMessage = "Không có tập tin để xem.";
                return false;
            }

            if (string.IsNullOrWhiteSpace(userName))
            {
                errorMessage = "Phiên làm việc đã hết. Vui lòng đăng nhập lại.";
                return false;
            }

            string physicalPath = GetPhysicalPathFromRelative(relativePath);
            if (!File.Exists(physicalPath))
            {
                errorMessage = "Tập tin không còn trên máy chủ.";
                return false;
            }

            string displayName = GetDisplayFileName(relativePath);
            string fileType = Path.GetExtension(physicalPath).TrimStart('.').ToLower(CultureInfo.InvariantCulture);
            if (fileType == "pdf" || fileType == "doc" || fileType == "docx" || fileType == "xls" || fileType == "xlsx")
            {
                url = DCore.Globals.ApplicationVRoot + string.Format(CultureInfo.InvariantCulture,
                    "/viewer.html?filetype={0}&key={1}",
                    fileType,
                    ViewFile.GenerateKeyForExport(physicalPath, displayName, userName, "Viet$cong"));
            }
            else
            {
                url = DCore.Globals.ApplicationVRoot + "/DownloadFile.ashx?key="
                    + DownloadFile.GenerateKeyForExport(physicalPath, displayName, userName, "Viet$minh");
            }

            return true;
        }

