private string GetLinkFromDataItem(object dataItem)
{
    return GetText(dataItem, "Link");
}

private string GetLinkFromRow(int rowIndex)
{
    if (rowIndex < 0 || rowIndex >= gvCongTac.Rows.Count)
        return string.Empty;

    GridViewRow row = gvCongTac.Rows[rowIndex];
    if (row == null)
        return string.Empty;

    return GetLinkFromDataItem(row.DataItem);
}

private void OpenAttachmentView(string relativePath)
{
